package com.yonlab.vision;
import android.content.Context;import android.os.SystemClock;import org.tensorflow.lite.*;import org.json.*;import java.io.*;import java.nio.*;import java.util.*;
/** YAMNet and PANNs families share timed comparison windows and worker-owned engines. */
public final class SoundEngine implements AutoCloseable {
 private Interpreter interpreter;private PannSoundEngine pann;private ByteBuffer model;public final String id,sha256;public final String[] labels;public final long loadMs;private boolean closed;
 public static String expected(String id){if(PannModels.supports(id))return PannModels.sha(id);if("yamnet-classifier".equals(id))return "10c95ea3eb9a7bb4cb8bddf6feb023250381008177ac162ce169694d05c317de";if("yamnet-original".equals(id))return "141fba1cdaae842c816f28edc4937e8b4f0af4c8df21862ccc6b52dc567993c3";throw new IllegalArgumentException("소리 모델을 선택하세요");}
 public SoundEngine(Context c,String modelId,SoundMath.Cancel cancel)throws Exception{
  long start=SystemClock.elapsedRealtime();id=modelId;sha256=expected(id);int size="yamnet-classifier".equals(id)?4126810:16096668;
  try{SoundMath.check(cancel);if(PannModels.supports(id)){pann=new PannSoundEngine(c,id,cancel);labels=pann.labels;loadMs=pann.loadMs;}else{OneLiteAsset asset=new OneLiteAsset(c,id+".tflite");SoundMath.check(cancel);if(asset.size!=size||!sha256.equals(asset.sha256))throw new IOException("소리 모델 해시를 확인하세요");model=asset.bytes;int threads=OneExecutionSettings.threads(c);interpreter=new Interpreter(model,new Interpreter.Options().setNumThreads(threads));interpreter.resizeInput(0,new int[]{SoundMath.WINDOW});interpreter.allocateTensors();if(interpreter.getInputTensor(0).dataType()!=DataType.FLOAT32||!Arrays.equals(interpreter.getInputTensor(0).shape(),new int[]{SoundMath.WINDOW})||interpreter.getOutputTensor(0).dataType()!=DataType.FLOAT32||!Arrays.equals(interpreter.getOutputTensor(0).shape(),new int[]{1,SoundMath.CLASSES}))throw new IOException("소리 모델 입출력 계약을 확인하세요");labels=labels(c);loadMs=SystemClock.elapsedRealtime()-start;}SoundMath.check(cancel);}catch(Exception|LinkageError|OutOfMemoryError e){try{close();}catch(Exception|LinkageError cleanup){e.addSuppressed(cleanup);}throw e;}
 }
 private static String[] labels(Context c)throws Exception{String[] result=new String[521];try(BufferedReader reader=new BufferedReader(new InputStreamReader(c.getAssets().open("one/yamnet-labels.csv"),"UTF-8"))){String line=reader.readLine();if(line==null||!line.startsWith("index,"))throw new IOException("소리 분류 목록");int count=0;while((line=reader.readLine())!=null){String[] row=SoundMath.csv(line);int index=Integer.parseInt(row[0]);if(row.length!=3||index!=count||index>=521)throw new IOException("소리 분류 목록");result[count++]=row[2];}if(count!=521)throw new IOException("소리 분류 목록");}return result;}
 public JSONObject analyze(float[] pcm,SoundMath.Cancel cancel)throws Exception{
  return analyze(pcm,null,SoundMath.RATE,cancel);
 }
 public JSONObject analyze(float[] pcm,float[] sourcePcm,int sourceRate,SoundMath.Cancel cancel)throws Exception{
  if(pann!=null)return pann.analyze(pcm,sourcePcm,sourceRate,cancel);
  if(closed)throw new IOException("소리 엔진이 종료되었습니다");long start=SystemClock.elapsedRealtime();float[] sum=new float[521],peak=new float[521];int[] starts=SoundMath.starts(pcm.length);JSONArray windows=new JSONArray();
  for(int offset:starts){SoundMath.check(cancel);float[][] result=new float[1][521];Map<Integer,Object> outputs=new HashMap<>();outputs.put(0,result);interpreter.runForMultipleInputsOutputs(new Object[]{SoundMath.window(pcm,offset)},outputs);SoundMath.check(cancel);for(int i=0;i<521;i++){float v=result[0][i];if(!Float.isFinite(v)||v<-.0001f||v>1.0001f)throw new IOException("소리 모델 출력");sum[i]+=v;peak[i]=Math.max(peak[i],v);}windows.put(new JSONObject().put("startSec",offset/16000d).put("endSec",Math.min(pcm.length,offset+SoundMath.WINDOW)/16000d).put("top",scores(result[0],peak,3)));}
  for(int i=0;i<521;i++)sum[i]/=starts.length;return new JSONObject().put("modelId",id).put("modelSha256",sha256).put("state","COMPLETED").put("loadMs",loadMs).put("inferenceMs",SystemClock.elapsedRealtime()-start).put("timingScope","ALL_WINDOWS_PREPARE_INFER_AND_RANK_EXCLUDING_AUDIO_DECODE_AND_MODEL_LOAD").put("windowSamples",15600).put("hopSamples",7680).put("windowCount",starts.length).put("zeroPadFinalWindow",true).put("classCount",521).put("top5",scores(sum,peak,5)).put("windows",windows).put("allClassMeans",new JSONArray(sum)).put("inputPcmSha256",SoundMath.pcmSha(pcm));
 }
 private JSONArray scores(float[] mean,float[] peak,int count)throws Exception{JSONArray out=new JSONArray();for(int index:SoundMath.top(mean,count))out.put(new JSONObject().put("classId",index).put("label",labels[index]).put("score",mean[index]).put("peak",peak[index]));return out;}
 @Override public synchronized void close(){if(closed)return;if(pann!=null){PannSoundEngine prior=pann;pann=null;prior.close();}if(interpreter!=null)try{interpreter.close();}finally{interpreter=null;model=null;}closed=true;}
 public boolean closed(){return closed;}
}
